<?php
declare(strict_types=1);
namespace App\Interface\Http\Assistant;
use App\Application\Assistant\DTO\Request\CreateAssistantConversationRequestDto;use App\Application\Assistant\DTO\Request\CreateAssistantMessageRequestDto;use InvalidArgumentException;use Psr\Http\Message\ServerRequestInterface;
final class AssistantRequestFactory { public function conversation(ServerRequestInterface $request):CreateAssistantConversationRequestDto{$p=$this->json($request);if(!is_string($p['syllabus_id']??null)||trim($p['syllabus_id'])==='')throw new InvalidArgumentException('Informe o edital.');$title=$p['title']??null;if($title!==null&&(!is_string($title)||mb_strlen(trim($title))>160))throw new InvalidArgumentException('Titulo invalido.');return new CreateAssistantConversationRequestDto($p['syllabus_id'],$title);} public function message(ServerRequestInterface $request,string $id):CreateAssistantMessageRequestDto{$p=$this->json($request);if(!is_string($p['content']??null)||mb_strlen(trim($p['content']))<3||mb_strlen(trim($p['content']))>2000)throw new InvalidArgumentException('A pergunta deve ter entre 3 e 2000 caracteres.');return new CreateAssistantMessageRequestDto($id,$p['content']);} private function json(ServerRequestInterface $request):array{try{$p=json_decode((string)$request->getBody(),true,512,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new InvalidArgumentException('JSON invalido.');}if(!is_array($p)||array_is_list($p))throw new InvalidArgumentException('O corpo deve ser um objeto JSON.');return $p;} }
